class Geo{public List<Vector3> p=new List<Vector3>();public List<Vector2> uv=new List<Vector2>();public List<Vector4> flags=new List<Vector4>();public List<Color> color=new List<Color>();public List<int> ids=new List<int>();public void Tri(Vector3 a,Vector3 b,Vector3 c,int tile,Color tint,float glow=0){int start=p.Count;var normal=Vector3.Cross(b-a,c-a).normalized;foreach(var v in new[]{a,b,c}){p.Add(v);uv.Add(Mathf.Abs(normal.y)>.6f?new Vector2(v.x/3,v.z/3):Mathf.Abs(normal.x)>.6f?new Vector2(v.z/3,v.y/3):new Vector2(v.x/3,v.y/3));flags.Add(new Vector4(tile,glow,0,0));color.Add(tint);}ids.AddRange(new[]{start,start+1,start+2});}public void Box(Vector3 q,Vector3 s,int tile,Color tint,float glow=0){var v=new Vector3[8];for(int i=0;i<8;i++)v[i]=q+Vector3.Scale(new Vector3((i&1)==0?-.5f:.5f,(i&2)==0?-.5f:.5f,(i&4)==0?-.5f:.5f),s);foreach(var f in new[]{new[]{0,2,3,1},new[]{4,5,7,6},new[]{0,1,5,4},new[]{2,6,7,3},new[]{0,4,6,2},new[]{1,3,7,5}}){Tri(v[f[0]],v[f[1]],v[f[2]],tile,tint,glow);Tri(v[f[0]],v[f[2]],v[f[3]],tile,tint,glow);}}public void Pole(Vector3 a,Vector3 b,float r,int tile,Color tint,int sides=8){var axis=(b-a).normalized;var u=Vector3.Cross(axis,Mathf.Abs(axis.y)>.9f?Vector3.forward:Vector3.up).normalized;var v=Vector3.Cross(axis,u);for(int k=0;k<sides;k++){var x=u*Mathf.Cos(k*Mathf.PI*2/sides)+v*Mathf.Sin(k*Mathf.PI*2/sides);var z=u*Mathf.Cos((k+1)*Mathf.PI*2/sides)+v*Mathf.Sin((k+1)*Mathf.PI*2/sides);Tri(a+x*r,a+z*r,b+x*r,tile,tint);Tri(a+z*r,b+z*r,b+x*r,tile,tint);Tri(a,a+z*r,a+x*r,tile,tint);Tri(b,b+x*r,b+z*r,tile,tint);}}public void Sphere(Vector3 center,Vector3 scale,Color tint){for(int ring=0;ring<4;ring++)for(int k=0;k<12;k++){Func<int,int,Vector3> point=(i,j)=>{float y=-Mathf.PI/2+i*Mathf.PI/4,a=j*Mathf.PI/6;return center+Vector3.Scale(new Vector3(Mathf.Cos(y)*Mathf.Cos(a),Mathf.Sin(y),Mathf.Cos(y)*Mathf.Sin(a)),scale);};var a=point(ring,k);var b=point(ring,k+1);var c=point(ring+1,k);var d=point(ring+1,k+1);Tri(a,c,b,-1,tint);Tri(b,c,d,-1,tint);}}public Mesh Save(string name){var mesh=new Mesh{name=name,indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};mesh.SetVertices(p);mesh.SetUVs(0,uv);mesh.SetUVs(1,flags);mesh.SetColors(color);mesh.SetTriangles(ids,0);mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,D+"/Meshes/"+name+".asset");return mesh;}}
